THOUGHT: The changes look good. Now let me create a simple test script to verify that our fixes work correctly:

```bash
cat <<'EOF' > test_fix.go
package main

import (
	"fmt"
	"./bitset"
)

func main() {
	// Test NextSet fix
	v := bitset.New(10000)
	v.Set(0)
	v.Set(1)
	v.Set(2)

	data := make([]uint, 3)
	c := 0
	for i, e := v.NextSet(0); e; i, e = v.NextSet(i + 1) {
		data[c] = i
		c++
		if c >= 3 {
			break
		}
	}

	fmt.Printf("NextSet results: %v\n", data)

	// Test NextClear fix
	v2 := bitset.New(1000)
	v2.Set(0).Set(1)
	next, found := v2.NextClear(0)
	fmt.Printf("NextClear(0) = %d, found = %v\n", next, found)

	if !found || next != 2 {
		fmt.Printf("ERROR: Expected NextClear(0) to return (2, true), got (%d, %v)\n", next, found)
	} else {
		fmt.Printf("SUCCESS: NextClear works correctly\n")
	}
}
EOF
```

